listOpenTabs.description:
Public source contract from @vibestudio/browser-data/client. Referenced dependency types retain their source names and imports.

```ts
export interface ImportedBrowserOpenTab {
  tabId: string;
  url: string;
  title?: string;
  active: boolean;
  pinned?: boolean;
  lastAccessed?: number;
  /**
   * Opaque identifier for the source browser window this tab belongs to. Tabs
   * sharing a `windowId` were open side by side; the value carries no profile
   * path or window handle, only grouping identity.
   */
  windowId: string;
  /** 1-based window position, stable across profiles, for display ("Window 2"). */
  windowOrdinal: number;
  /**
   * How this tab relates to what the user would actually see:
   * `open` — the profile is running and the tab is open right now;
   * `restores` — the browser is closed, but launching it reopens this window;
   * `saved` — a stored session that will not come back on its own (another
   * profile launches by default, or session restore is switched off).
   */
  sessionState: BrowserTabSessionState;
}

export type BrowserTabSessionState = (typeof BROWSER_TAB_SESSION_STATES)[number];
```

openTabsAsPanels.description:
Public source contract from @vibestudio/browser-data/client. Referenced dependency types retain their source names and imports.

```ts
export interface OpenTabsAsPanelsRequest {
  hostId: string;
  sourceId: string;
  selection: string[];
  /**
   * Where the imported hierarchy is anchored. A new root keeps migration
   * tooling out of the imported browser's lasting workspace structure.
   */
  destination?: OpenTabsPanelDestination;
  /** "window" adds one nested collection per source-browser window. */
  groupBy?: OpenTabsPanelGrouping;
}

export interface OpenTabsAsPanelsResult {
  destination: OpenTabsPanelDestination;
  groupBy: OpenTabsPanelGrouping;
  tabsFound: number;
  panelsOpened: number;
  /** The new root collection, when `destination` is `"new-root"`. */
  root?: {
    id: string;
    title: string;
    panelsOpened: number;
  };
  /** Non-root collection panels created for source-browser windows. */
  collections: Array<{
    id: string;
    title: string;
    parentId: string;
    panelsOpened: number;
  }>;
  panels: Array<{
    id: string;
    title: string;
    url: string;
  }>;
  skipped: Array<{
    url: string;
    reason: string;
  }>;
}

export type OpenTabsPanelDestination = "new-root" | "caller";

export type OpenTabsPanelGrouping = "window" | "none";
```

